/* cppi::f276fbc61ffcf9fe77b3ebb8d20c77a5ddc8f20be619e01eedd5ba9e9bcaf4a2 */
select trade_date, business_date, changed_date, abor_transaction_number, cost_or_tax_present, transaction_cancellation_flag, rn
from (
    SELECT *,
           ROW_NUMBER() OVER (
               PARTITION BY scd_transaction_number_primary_key
						order by
							changed_date desc -- change date is actual loaded date so use this to get the latest data.
           ) AS rn
    FROM trades_deals.scd_transactions
    WHERE accounting_framework_id = 'PCLFWKMAIN'
)
where abor_transaction_number = 20250613015521

/* cppi::9f849bab3163bb5af0335b263a1f4f08604284beb28308e61402b678c740cba4 */
select business_date as date_, security_id, 'MS757951' as strategy_id, weight_ndo as weight
                                  from (select * from (select *, ROW_NUMBER() OVER (PARTITION by business_date, id_vendor_security_ndo, id_cppib_index order by feed_version asc) as rn from market.cppib_market_index_constituents_mapped_rimes) where rn = 1)
                                  where business_date >= date '2025-06-18' and business_date <= date '2025-06-18' and weight_ndo>0 and id_cppib_index = 'MS757951_GR_USD_0_0' and security_id is not null

